          {onOpenHistory && (
            <Button
              variant="outline"
              size="sm"
              onClick={onOpenHistory}
              className="gap-1.5 text-xs"
            >
              <History className="size-3.5" />
              Version History
            </Button>
          )}
          <Button variant="outline" size="sm" onClick={() => setTemplatesOpen(true)} className="text-xs">
            Templates
          </Button>
          {onViewVersions && (
            <Button
              variant="outline"
              size="sm"
              onClick={onViewVersions}
              className="gap-1.5 text-xs text-primary border-primary/20 hover:bg-primary/5"
